messages.content:
Return the requested retrievalReport via set_output. Every record needs a clear statement, provenance kind, original host category when supplied, evidence locations and caveats. Cite existing host evidence refs for verifiedKnowledge; absence means no claimed verification. Mark partial/unavailable and list omitted scopes. Perform no cleanup or promotion.

## Output Schema

When using the set_output tool, your output must conform to this schema. You may pass the fields either directly as top-level parameters or inside a `data` field — both are accepted. Pass native object values; never call JSON.stringify or put serialized JSON text inside `data`.

```json
{
  "type": "object",
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "status": {
      "type": "string",
      "enum": [
        "complete",
        "partial",
        "unavailable"
      ]
    },
    "scope": {
      "type": "array",
      "items": {
        "type": "string",
        "maxLength": 1024
      },
      "maxItems": 64
    },
    "summary": {
      "type": "string",
      "maxLength": 4000
    },
    "records": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1,
            "maxLength": 160
          },
          "statement": {
            "type": "string",
            "minLength": 1,
            "maxLength": 4000
          },
          "sourceKind": {
            "type": "string",
            "enum": [
              "knowledge-file",
              "code-map",
              "repository-knowledge",
              "procedure",
              "memory"
            ]
          },
          "canonicalCategory": {
            "type": "string",
            "enum": [
              "verifiedKnowledge",
              "reusableDiscovery",
              "rereadRequired",
              "none"
            ]
          },
          "hostEvidenceRefs": {
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 1024,
              "pattern": "\\S"
            },
            "maxItems": 64
          },
          "evidence": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "kind": {
                  "type": "string",
                  "enum": [
                    "file",
                    "index",
                    "memory",
                    "validation"
                  ]
                },
                "locator": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1024,
                  "pattern": "^(?![\\\\/])(?![A-Za-z]:)(?![\\s\\S]*(?:^|[\\\\/])\\.\\.(?:[\\\\/]|$))[^\\u0000-\\u001f\\u007f\\u2028\\u2029]+$"
                },
                "startLine": {
                  "type": "integer",
                  "minimum": 1
                },
                "endLine": {
                  "type": "integer",
                  "minimum": 1
                },
                "contentHash": {
                  "type": "string",
                  "maxLength": 256
                },
                "receiptRef": {
                  "type": "string",
                  "maxLength": 1024
                }
              },
              "required": [
                "kind",
                "locator"
              ]
            },
            "maxItems": 16,
            "minItems": 1
          },
          "caveats": {
            "type": "array",
            "items": {
              "type": "string",
              "maxLength": 1024
            },
            "maxItems": 64
          }
        },
        "required": [
          "id",
          "statement",
          "sourceKind",
          "canonicalCategory",
          "evidence",
          "caveats"
        ],
        "if": {
          "properties": {
            "canonicalCategory": {
              "const": "verifiedKnowledge"
            }
          },
          "required": [
            "canonicalCategory"
          ]
        },
        "then": {
          "properties": {
            "hostEvidenceRefs": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 1024,
                "pattern": "\\S"
              },
              "maxItems": 64,
              "minItems": 1
            }
          },
          "required": [
            "hostEvidenceRefs"
          ]
        }
      },
      "maxItems": 40
    },
    "omissions": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "scope": {
            "type": "string",
            "maxLength": 1024
          },
          "reason": {
            "type": "string",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "scope",
          "reason"
        ]
      }
    }
  },
  "required": [
    "schemaVersion",
    "status",
    "scope",
    "summary",
    "records",
    "omissions"
  ],
  "additionalProperties": false,
  "if": {
    "properties": {
      "status": {
        "const": "complete"
      }
    },
    "required": [
      "status"
    ]
  },
  "then": {
    "properties": {
      "omissions": {
        "type": "array",
        "maxItems": 0,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "scope": {
              "type": "string",
              "maxLength": 1024
            },
            "reason": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000
            }
          },
          "required": [
            "scope",
            "reason"
          ]
        }
      }
    }
  }
}
```

function.description:
Lists all files and directories in the specified path. Useful for exploring directory structure and finding files.

Returns up to 5000 entries per page. When truncated is true, call again with offset set to nextOffset to retrieve the remaining entries. Pages reflect the current directory; restart at offset 0 if its contents change. Failures return an errorMessage naming the requested path, plus the errno code when the filesystem reports one.

Example:
<list_directory_params_example>
{
  "path": "src/components"
}
</list_directory_params_example>

<list_directory_params_example>
{
  "path": "."
}
</list_directory_params_example>
